    return lookup(Gcb, cp, &gcb_ranges, .other);
}
pub fn isExtendedPictographic(cp: u21) bool {
    return lookup(Bool, cp, &extended_pictographic_ranges, .no) == .yes;
}
pub fn incb(cp: u21) InCB {
    return lookup(InCB, cp, &incb_ranges, .none);
}
